export const contentFactory = (type, token) => {
  const API_BASE = "http://127.0.0.1:8000/api";

  switch (type) {
    case "article":
      return async (articleData) => {
        const formData = new FormData();
        Object.entries(articleData).forEach(([key, value]) => formData.append(key, value));

        const res = await fetch(`${API_BASE}/articles/`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: formData,
        });

        if (!res.ok) throw new Error("Не вдалося створити статтю");
        return await res.json();
      };

    case "poll":
      return async (pollData) => {
        // 1️⃣ Спочатку створюємо статтю типу interactive
        const articleForm = new FormData();
        articleForm.append("title", pollData.question);
        const uniqueSlug = pollData.question.toLowerCase().replace(/\s+/g, "-") + "-" + Date.now();
        articleForm.append("slug", uniqueSlug);
        articleForm.append("content", "");
        articleForm.append("excerpt", "");
        articleForm.append("status", "published");
        articleForm.append("type", "interactive");
        articleForm.append("category", "News");
        articleForm.append("is_premium", "false");
        if (pollData.channel) articleForm.append("channel", pollData.channel);

        const articleRes = await fetch(`${API_BASE}/articles/`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: articleForm,
        });

        if (!articleRes.ok) {
          const errData = await articleRes.json();
          console.error("📛 Помилка створення статті:", errData);
          throw new Error("Не вдалося створити статтю для опитування");
        }
        const article = await articleRes.json();

        // 2️⃣ Тепер створюємо опитування
        const pollRes = await fetch(`${API_BASE}/polls/`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            article: article.id,
            question: pollData.question,
            choices: pollData.options.map((text) => ({ text })),
            channel: pollData.channel || null,
          }),
        });

        if (!pollRes.ok) throw new Error("Не вдалося створити опитування");
        return await pollRes.json();
      };

    default:
      throw new Error("Невідомий тип контенту");
  }
};
